:root {
  --bg: #1b1a2e;
  --bg2: #2a2745;
  --ink: #f4efe4;
  --muted: #a39fbf;
  --gold1: #ffe08a;
  --gold2: #e6b23c;
  --gold3: #a8751a;
  --silver1: #f1f3f7;
  --silver2: #b9bfcc;
  --silver3: #7a8194;
  --accent: #ff8a5c;
}

* { box-sizing: border-box; margin: 0; padding: 0; }

html, body { height: 100%; }

body {
  font-family: -apple-system, BlinkMacSystemFont, "SF Pro Rounded", "Segoe UI", system-ui, sans-serif;
  color: var(--ink);
  background: radial-gradient(120% 80% at 50% 0%, var(--bg2), var(--bg) 65%);
  -webkit-font-smoothing: antialiased;
  -webkit-tap-highlight-color: transparent;
}

.app {
  min-height: 100%;
  max-width: 420px;
  margin: 0 auto;
  padding: calc(40px + env(safe-area-inset-top)) 24px calc(32px + env(safe-area-inset-bottom));
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 22px;
}

header { text-align: center; }
h1 { font-size: 34px; font-weight: 800; letter-spacing: -0.02em; }
.sub { margin-top: 6px; color: var(--muted); font-size: 15px; }

/* coin */
.stage {
  position: relative;
  width: 200px;
  height: 260px;
  border: 0;
  background: none;
  cursor: pointer;
  perspective: 900px;
  display: flex;
  align-items: center;
  justify-content: center;
  outline: none;
}
.stage:focus-visible .coin { box-shadow: 0 0 0 4px rgba(255,138,92,.5); border-radius: 50%; }

.coin {
  position: relative;
  width: 170px;
  height: 170px;
  transform-style: preserve-3d;
  transition: transform 0.2s ease;
}
.stage:active .coin { transform: scale(0.96); }

.face {
  position: absolute;
  inset: 0;
  border-radius: 50%;
  backface-visibility: hidden;
  -webkit-backface-visibility: hidden;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  font-weight: 800;
}
.face span { font-size: 72px; line-height: 1; }
.face small { font-size: 12px; letter-spacing: 0.25em; text-transform: uppercase; margin-top: 4px; opacity: .75; }

.heads {
  background: radial-gradient(circle at 32% 28%, var(--gold1), var(--gold2) 55%, var(--gold3));
  color: #7a4f0a;
  box-shadow: inset 0 0 0 8px rgba(255,255,255,.18), inset 0 0 0 11px rgba(122,79,10,.35), 0 10px 30px rgba(230,178,60,.25);
  text-shadow: 0 1px 0 rgba(255,240,200,.6);
}
.tails {
  background: radial-gradient(circle at 32% 28%, var(--silver1), var(--silver2) 55%, var(--silver3));
  color: #4b5162;
  transform: rotateY(180deg);
  box-shadow: inset 0 0 0 8px rgba(255,255,255,.25), inset 0 0 0 11px rgba(75,81,98,.35), 0 10px 30px rgba(185,191,204,.2);
  text-shadow: 0 1px 0 rgba(255,255,255,.7);
}

.shadow {
  position: absolute;
  bottom: 18px;
  left: 50%;
  width: 130px;
  height: 16px;
  margin-left: -65px;
  border-radius: 50%;
  background: rgba(0,0,0,.35);
  filter: blur(6px);
  transition: transform .2s ease, opacity .2s ease;
}

.flipping .shadow { animation: shadow 1.1s cubic-bezier(.3,.7,.4,1); }
@keyframes shadow {
  0%, 100% { transform: scale(1); opacity: 1; }
  45% { transform: scale(.45); opacity: .35; }
}

.result {
  min-height: 34px;
  font-size: 26px;
  font-weight: 800;
  letter-spacing: -0.01em;
}
.result.pop { animation: pop .35s cubic-bezier(.2,1.6,.4,1); }
@keyframes pop { from { transform: scale(.6); opacity: 0; } to { transform: scale(1); opacity: 1; } }
.result.h { color: var(--gold1); }
.result.t { color: var(--silver1); }

.stats {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 10px;
  width: 100%;
}
.stat {
  background: rgba(255,255,255,.05);
  border: 1px solid rgba(255,255,255,.07);
  border-radius: 16px;
  padding: 14px 8px;
  text-align: center;
}
.stat b { display: block; font-size: 24px; font-variant-numeric: tabular-nums; }
.stat span { font-size: 12px; color: var(--muted); letter-spacing: .08em; text-transform: uppercase; }

.history {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 6px;
  min-height: 26px;
  width: 100%;
}
.dot {
  width: 22px;
  height: 22px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  font-size: 11px;
  font-weight: 800;
  animation: pop .3s ease;
}
.dot.h { background: var(--gold2); color: #5c3a05; }
.dot.t { background: var(--silver2); color: #3a3f4d; }

.reset {
  margin-top: auto;
  background: none;
  border: 1px solid rgba(255,255,255,.14);
  color: var(--muted);
  font: inherit;
  font-size: 14px;
  padding: 9px 20px;
  border-radius: 999px;
  cursor: pointer;
  transition: color .2s, border-color .2s;
}
.reset:hover { color: var(--accent); border-color: var(--accent); }

@media (prefers-reduced-motion: reduce) {
  .coin { transition: none !important; }
  .flipping .shadow, .result.pop, .dot { animation: none; }
}

