events.content:
(() => {
  const KEY = "flip.v1";
  const MAX_HISTORY = 24;
  const reduced = window.matchMedia("(prefers-reduced-motion: reduce)").matches;

  const $ = (id) => document.getElementById(id);
  const stage = $("coinBtn");
  const coin = $("coin");
  const result = $("result");
  const hCount = $("hCount");
  const tCount = $("tCount");
  const streakEl = $("streak");
  const history = $("history");

  let state = load();
  let rotation = state.last === "t" ? 180 : 0;
  let busy = false;

  coin.style.transform = `rotateY(${rotation}deg)`;
  render();

  function load() {
    try {
      const s = JSON.parse(localStorage.getItem(KEY));
      if (s && Array.isArray(s.history)) return s;
    } catch (_) {}
    return { h: 0, t: 0, history: [], last: null };
  }

  function save() {
    try { localStorage.setItem(KEY, JSON.stringify(state)); } catch (_) {}
  }

  function fairBit() {
    const a = new Uint8Array(1);
    crypto.getRandomValues(a);
    return a[0] & 1;
  }

  function currentStreak() {
    const h = state.history;
    if (!h.length) return 0;
    let n = 1;
    for (let i = h.length - 2; i >= 0 && h[i] === h[h.length - 1]; i--) n++;
    return n;
  }

  function render() {
    hCount.textContent = state.h;
    tCount.textContent = state.t;
    streakEl.textContent = currentStreak();
    history.innerHTML = "";
    state.history.slice(-MAX_HISTORY).forEach((r) => {
      const d = document.createElement("span");
      d.className = `dot ${r}`;
      d.textContent = r.toUpperCase();
      history.appendChild(d);
    });
  }

  function showResult(r) {
    result.className = "result";
    void result.offsetWidth;
    const streak = currentStreak();
    const word = r === "h" ? "Heads" : "Tails";
    result.textContent = streak >= 3 ? `${word} ×${streak}` : `${word}!`;
    result.className = `result pop ${r}`;
  }

  function flip() {
    if (busy) return;
    busy = true;
    const r = fairBit() ? "h" : "t";
    result.className = "result";
    result.innerHTML = "&nbsp;";

    // spin 5–7 full turns, landing on the right face
    const turns = 5 + Math.floor(Math.random() * 3);
    const base = rotation - (rotation % 360) + turns * 360;
    rotation = base + (r === "t" ? 180 : 0);

    const duration = reduced ? 0 : 1100;
    coin.style.transition = reduced ? "none" : `transform ${duration}ms cubic-bezier(.3,.7,.4,1)`;
    coin.animate && !reduced && coin.animate(
      [
        { translate: "0 0" },
        { translate: "0 -90px", offset: 0.45 },
        { translate: "0 0" }
      ],
      { duration, easing: "cubic-bezier(.3,.7,.4,1)" }
    );
    stage.classList.add("flipping");
    coin.style.transform = `rotateY(${rotation}deg)`;

    setTimeout(() => {
      stage.classList.remove("flipping");
      state[r]++;
      state.last = r;
      state.history.push(r);
      if (state.history.length > MAX_HISTORY) state.history = state.history.slice(-MAX_HISTORY);
      save();
      render();
      showResult(r);
      if (navigator.vibrate) navigator.vibrate(18);
      busy = false;
    }, duration);
  }

  stage.addEventListener("click", flip);
  document.addEventListener("keydown", (e) => {
    if ((e.key === " " || e.key === "Enter") && e.target === document.body) {
      e.preventDefault();
      flip();
    }
  });

  $("reset").addEventListener("click", () => {
    state = { h: 0, t: 0, history: [], last: state.last };
    save();
    render();
    result.className = "result";
    result.innerHTML = "&nbsp;";
  });
})();
